  _stateSignature(hass){return Object.values(hass?.states||{}).filter(s=>SUPPORTED.has(domainOf(s.entity_id))||domainOf(s.entity_id)==="weather"||/(parash|parsh|weekly_portion|candle|havdalah|shabbat)/i.test(s.entity_id)).map(s=>{const a=s.attributes||{};return [s.entity_id,s.state,a.brightness,a.current_position,a.volume_level,a.is_volume_muted,a.media_title,a.source,a.entity_picture,a.access_token,a.frontend_stream_type,a.supported_features,a.current_temperature,a.temperature,a.target_temp_low,a.target_temp_high,a.humidity,a.hvac_action,a.hvac_modes,a.fan_mode,a.fan_modes,a.preset_mode,a.preset_modes,a.swing_mode,a.swing_modes,a.swing_horizontal_mode,a.swing_horizontal_modes].join("|")}).sort().join(";")}

