        const unavailable=["unavailable","unknown"].includes(state.state),badge=card.querySelector(".cameraLiveBadge"),host=card.querySelector("[data-camera-host]");if(badge){badge.textContent=unavailable?this._t("unavailable"):this._t("live");badge.classList.toggle("offline",unavailable)}
