    this.shadowRoot.querySelectorAll("[data-camera-card]").forEach(card=>{if(this._hass.states[card.dataset.cameraCard])card.hass=this._hass});
    const visible=this._overviewEntries();
    const metrics={lights:visible.filter(s=>this._displayCategory(s)==="light"&&isOn(s.state)).length,switches:visible.filter(s=>this._displayCategory(s)==="switch"&&isOn(s.state)).length,climate:visible.filter(s=>this._displayCategory(s)==="climate"&&isOn(s.state)).length,covers:visible.filter(s=>this._displayCategory(s)==="cover"&&isOn(s.state)).length};
    const metricValues=[metrics.lights,metrics.switches,metrics.climate,metrics.covers];this.shadowRoot.querySelectorAll(".clyMetric b").forEach((target,index)=>{if(metricValues[index]!==undefined)target.textContent=String(metricValues[index])});
