    if(el.dataset.cameraClose!==undefined){if(el.tagName==="BUTTON"||event.target===el){this._cameraFocus=null;this._cameraZoom=1;this._cameraPan={x:0,y:0};this._cameraDrag=null;this._render()}return}
    if(el.dataset.cameraOpen){const state=this._hass.states[el.dataset.cameraOpen];if(state){this._cameraFocus=state.entity_id;this._detail=null;this._cameraZoom=1;this._cameraPan={x:0,y:0};this._render()}return}
