    if(el.dataset.cameraPage){const pages=Math.max(1,Math.ceil(this._cameraEntities().length/this._cameraGridCount)),delta=el.dataset.cameraPage==="next"?1:-1;this._cameraPage=Math.max(0,Math.min(pages-1,this._cameraPage+delta));this._render();return}
