    if(el.dataset.settingsSection){this._settingsSection=el.dataset.settingsSection;this._render();return}
    if(el.dataset.deviceMode){this._homeDeviceMode=el.dataset.deviceMode==="all"?"all":"active";this._renderKeepingScroll();return}
    if(el.dataset.selectUnassigned!==undefined){const entries=this._nativeUnassignedEntries(),allSelected=entries.length&&entries.every(state=>this._unassignedSelection.has(state.entity_id));this._unassignedSelection=allSelected?new Set():new Set(entries.map(state=>state.entity_id));this._render();return}
