    if(el.dataset.view){this._view=el.dataset.view;this._selectedArea=null;this._selectedFloor=null;this._detail=null;this._cameraFocus=null;this._filter="all";if(this._view==="cameras")this._cameraPage=0;this._render();return}
    if(el.dataset.floor){this._selectedFloor=el.dataset.floor;this._view="floor";this._detail=null;this._cameraFocus=null;this._filter="all";this._render();return}
    if(el.dataset.area){this._selectedArea=el.dataset.area;this._view="area";this._detail=null;this._cameraFocus=null;this._filter="all";this._render();return}
    if(el.dataset.quick){const s=this._hass.states[el.dataset.quick];if(s)this._action(s,"toggle");return}
    if(el.dataset.entity){this._detail=this._hass.states[el.dataset.entity];this._render();return}
