    if(el.dataset.more){this._moreInfo(el.dataset.more);return}
    if(el.id==="saveConfig"){this._saveConfig();return}if(el.id==="saveHomeInfo"){this._saveHomeInfo();return}if(el.id==="saveCategories"){this._saveCategories();return}if(el.id==="saveBackgrounds"){this._saveBackgrounds();return}if(el.id==="saveEntityOverrides"){this._saveEntityOverrides();return}if(el.id==="saveAreaFilters"){this._saveAreaFilters();return}if(el.id==="saveAreas"){this._saveAreas();return}if(el.id==="refreshAreas"){this._refreshData();return}if(el.id==="loadAdmin"){this._loadAdmin();return}if(el.id==="addPolicy"){this._addPolicy();return}
